import {t,label,ui,markup} from './language.mjs';
import {api} from './accounts.mjs';
import {updateMaternalRequirements} from './forms.mjs';
import {today} from './core.mjs';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function maternalInputs(prefix='join'){
 return ui`<div class="form-grid maternal-onboarding"><div class="field"><label for="${prefix}-age">Age in years</label><input id="${prefix}-age" name="age" type="number" min="12" max="60" step="1" required></div><div class="field"><label for="${prefix}-pregnancy">Current pregnancy status</label><select id="${prefix}-pregnancy" name="pregnancyStatus" required><option value="Pregnant">${label('Pregnant')}</option><option value="Not pregnant">${label('Not pregnant')}</option></select></div><div class="field"><label for="${prefix}-edd">Expected delivery date</label><input id="${prefix}-edd" name="edd" type="date" min="${today()}" required></div><div class="field wide"><label for="${prefix}-contact">Contact number</label><input id="${prefix}-contact" name="contact" type="tel" maxlength="40"></div><div class="field wide"><label for="${prefix}-barangay">Barangay / location</label><input id="${prefix}-barangay" name="barangay" maxlength="100"></div></div>`;
}
export function familyPanel(store){
 if(store.account.role==='staff')return '';
 const family=store.family??{},kind=store.account.kind;
 if(!kind||(kind==='mother'&&!store.account.maternalId)){
  const mothers=store.data.mothers;
  return ui`<details class="panel family-panel"><summary>Set up my personal profile</summary><p class="eyebrow">YOUR PERSONAL CARE PROFILE</p><h2>One account, your own care record.</h2><p>Choose your account type once. Existing records stay with the clinic; they are never merged or deleted.</p><form id="family-setup"><div class="field"><label for="family-kind">I am a</label><select id="family-kind" name="kind" ${kind?'disabled':''}><option value="mother">Mother</option>${!kind?markup('<option value="father">Father / companion</option>'):''}</select></div><div id="family-maternal">${mothers.length?ui`<div class="field"><label for="family-maternal-id">Choose my personal maternal record</label><select id="family-maternal-id" name="maternalId" required><option value="">Choose my record…</option>${mothers.map(m=>ui`<option value="${escape(m.id)}">${escape(m.name)} · ${m.id}</option>`).join('')}</select></div>`:maternalInputs('family')}<p class="data-note">Choose only your own record. Ask your health worker to correct a missing or incorrect link.</p></div><p id="family-error" class="notice warning" role="alert" hidden></p><button class="button primary" type="submit">Set up my profile ↗</button></form></details>`;
 }
 if(kind==='father')return ui`<section class="panel family-panel companion-panel"><span class="companion-mark" aria-hidden="true">♡</span><p class="eyebrow">HERE TO SUPPORT HER</p><h1>${label(family.partner?'Connected, with her permission.':'Care starts with her invitation.')}</h1>${family.partner?ui`<p>${escape(family.partner.name)}</p><p>You can view her shared maternal and child records. Only the mother and clinic staff can update them.</p><a class="button primary" href="#workspace/mothers">View shared care records ↗</a>`:markup('<p>Ask the mother to open My profile, choose Companion access, and share her pairing code with you. She can disconnect access at any time.</p><form id="family-pair"><div class="field"><label for="pairing-code">Pairing code from the mother</label><input id="pairing-code" name="code" autocomplete="off" autocapitalize="characters" spellcheck="false" maxlength="40" required placeholder="XXXX-XXXX-XXXX-XXXX-XXXX-XXXX"></div><p id="family-error" class="notice warning" role="alert" hidden></p><button class="button primary" type="submit">Connect to her account ↗</button></form>')}<p class="data-note">Companion access is read-only. A pairing code expires after 15 minutes and can be used once.</p></section>`;
 return '';
}
export function companionSettings(store){
 if(store.account.role!=="patient"||store.account.kind!=="mother")return "";
 const companions=store.family?.companions??(store.family?.partner?[store.family.partner]:[]),full=companions.length>=3;
 return ui`<section class="family-panel" aria-label="Companion access"><p class="companion-count">${label("{count} of 3 companions connected",{count:companions.length})}</p><p>Invite up to 3 companions to view your maternal and linked child records, checkups and vaccinations. They cannot edit them.</p>${companions.length?ui`<ul class="companion-list">${companions.map(person=>ui`<li class="companion-person"><div><strong>${escape(person.name)}</strong>${person.username?ui`<small>@${escape(person.username)}</small>`:""}<span class="badge">Read-only</span></div><button class="button secondary" data-disconnect-companion="${escape(person.id)}" data-companion-name="${escape(person.name)}" type="button">Disconnect companion</button></li>`).join("")}</ul>`:markup("<p>No companions connected yet.</p>")}${full?markup("<p class=\"notice\">You have reached the limit of 3 companions. Disconnect one before inviting someone else.</p>"):""}<p>Share each pairing code only with the person you want to invite. Each code can be used once.</p><button class="button primary" id="family-code" type="button" ${full?"disabled":""}>Create pairing code</button><div id="pairing-result" role="status"></div><p id="family-error" class="notice warning" role="alert" hidden></p><p class="data-note">Disconnecting stops future cloud access. A copy already downloaded to their device cannot be remotely erased.</p></section>`;
}
export function mountFamily(root,store,onChange){
 const fail=error=>{const out=root.querySelector('#family-error');if(out){out.textContent=t(error.message);out.hidden=false;}};
 const busy=async(form,action)=>{const controls=[...form.querySelectorAll('button,input,select')],states=controls.map(c=>c.disabled);controls.forEach(c=>c.disabled=true);try{await action();}catch(error){fail(error);}finally{controls.forEach((c,i)=>c.disabled=states[i]);}};
 const kind=root.querySelector('#family-kind'),maternal=root.querySelector('#family-maternal');
 if(kind)kind.onchange=()=>{maternal.hidden=kind.value==='father';for(const c of maternal.querySelectorAll('input,select'))c.disabled=maternal.hidden;updateMaternalRequirements(root);};
 root.querySelector('[name=pregnancyStatus]')?.addEventListener('change',()=>updateMaternalRequirements(root));updateMaternalRequirements(root);
 const setup=root.querySelector('#family-setup');if(setup)setup.onsubmit=event=>{event.preventDefault();const input=Object.fromEntries(new FormData(setup));input.kind=kind.value;void busy(setup,async()=>{if(store.pending)throw new Error('Sync your pending changes before setting up your personal profile.');const result=await api('family/setup',{method:'POST',proof:store.proof,body:input});store.account=result.account;await store.load();onChange();});};
 const pair=root.querySelector('#family-pair');if(pair)pair.onsubmit=event=>{event.preventDefault();const code=pair.elements.code.value;void busy(pair,async()=>{await api('family/pair',{method:'POST',proof:store.proof,body:{code}});await store.load();onChange();});};
 const code=root.querySelector('#family-code');if(code)code.onclick=()=>void busy(root,async()=>{const result=await api('family/code',{method:'POST',proof:store.proof,body:{}});root.querySelector('#pairing-result').innerHTML=ui`<p>Pairing code</p><strong class="pairing-code">${escape(result.code)}</strong><p>Valid for 15 minutes. Creating a new code cancels the previous one.</p>`;});
 for(const disconnect of root.querySelectorAll("[data-disconnect-companion]"))disconnect.onclick=()=>{if(!window.confirm(t("Disconnect {name} from your records?",{name:disconnect.dataset.companionName})))return;void busy(root,async()=>{await api("family/disconnect",{method:"POST",proof:store.proof,body:{companionId:disconnect.dataset.disconnectCompanion}});await store.load();onChange();});};
}
